def migrate_zone(self, text: str) -> str:
    """校验并迁移配置文本为规范 v2 文本，不改变任何状态。

    语义与模块级 migrate_zone 完全一致：text 非 str 抛 TypeError，
    配置错误沿用 ConfigError、RecordError、ZoneError。仅完成校验与
    规范化，不换区、不触碰修订号、缓存、统计与时钟。
    """
    return migrate_zone(text)

def migrate_zone_tx(self, text: str, expected: int) -> str:
    """带修订号检查的配置迁移原子换区事务。

    参数类型与 expected 范围校验同 reload_zone_tx（TypeError、
    ConfigError）。expected 不等于当前修订号时不解析 text，报告
    conflict（version 为当前修订号），不改变任何状态。相等时由
    migrate_zone 迁移得到规范 v2 文本，并以迁移后的 zone 构造候选
    PositiveCache，失败沿用 ConfigError、RecordError、ZoneError 且
    状态不变；候选区域与当前区域规范化后等价时报告 unchanged，
    版本与缓存不变；否则校验全部成功后原子换区（清空权威缓存，
    保留递归缓存、时钟、plan 与统计），修订号加 1 并报告 applied
    （version 为新修订号，stats() 提交当下逐字节不变）。版本、缓存
    与统计语义完全沿用 reload_zone_tx。报告为键序 version,result 的
    紧凑 ASCII JSON（末尾单换行），规范 v2 文本不嵌入报告。
    """
    if not isinstance(text, str):
        raise TypeError("text must be str")
    if not isinstance(expected, int) or isinstance(expected, bool):
        raise TypeError("expected must be int")
    if expected < 0:
        raise ConfigError("expected revision must be non-negative")
    if expected != self._revision:
        # 修订号不匹配：不得解析 text，冲突本身不改变任何状态。
        return self._tx_report(self._revision, "conflict")
    # 先迁移文本并构造候选缓存，全部成功后才提交；任何失败都回滚。
    migrated = migrate_zone(text)
    zone = import_zone(migrated)
    cache = PositiveCache(zone)
    current_text = export_zone(
        {"origin": _labels_to_name(self._cache._origin),
         "records": [_rr_to_model(rr) for rr in self._cache._records]})
    if export_zone(zone) == current_text:
        # 候选与当前区域规范化后等价：不换区、不加修订号。
        return self._tx_report(self._revision, "unchanged")
    self._cache = cache
    self._revision += 1
    return self._tx_report(self._revision, "applied")

